<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';require_role('administrador');$pageTitle='Imágenes';$errors=[];$current=null;$categories=db()->query("SELECT id,nombre FROM categorias WHERE tipo='imagen' ORDER BY nombre")->fetchAll();
$load=function(int$id):array{$s=db()->prepare('SELECT * FROM imagenes WHERE id=?');$s->execute([$id]);$r=$s->fetch();if(!$r){http_response_code(404);exit('Imagen no encontrada.');}return$r;};if(isset($_GET['t'])){$id=decode_id($_GET['t']);if(!$id)abort_forbidden('Token alterado.');$current=$load($id);}
if(request_is_post()){verify_csrf();$fa=clean_text($_POST['form_action']??'',20);if(in_array($fa,['create','update'],true)){$title=clean_text($_POST['titulo']??'',160);$alt=clean_text($_POST['texto_alt']??'',180);$section=clean_text($_POST['seccion']??'',100);$cat=filter_input(INPUT_POST,'categoria_id',FILTER_VALIDATE_INT)?:null;$active=isset($_POST['activo'])?1:0;if(mb_strlen($title)<3)$errors[]='Escribe un título.';if(mb_strlen($alt)<3)$errors[]='Escribe texto alternativo.';$id=$fa==='update'?decode_id($_POST['token_id']??''):null;if($fa==='update'&&!$id)abort_forbidden('Token alterado.');try{$new=upload_image($_FILES['archivo']??[],'images');}catch(RuntimeException$ex){$errors[]=$ex->getMessage();$new=null;}if($fa==='create'&&!$new)$errors[]='Selecciona una imagen.';if(!$errors){if($fa==='create')db()->prepare('INSERT INTO imagenes(categoria_id,titulo,ruta,texto_alt,seccion,activo)VALUES(?,?,?,?,?,?)')->execute([$cat,$title,$new,$alt,$section?:null,$active]);else{$old=$load($id);$path=$new?:$old['ruta'];db()->prepare('UPDATE imagenes SET categoria_id=?,titulo=?,ruta=?,texto_alt=?,seccion=?,activo=? WHERE id=?')->execute([$cat,$title,$path,$alt,$section?:null,$active,$id]);if($new)delete_uploaded_file($old['ruta']);}flash('success','Imagen guardada.');redirect('admin/imagenes.php');}}if($fa==='delete'){$id=decode_id($_POST['token_id']??'');if(!$id)abort_forbidden('Token alterado.');$old=$load($id);db()->prepare('DELETE FROM imagenes WHERE id=?')->execute([$id]);delete_uploaded_file($old['ruta']);flash('success','Imagen eliminada.');redirect('admin/imagenes.php');}}
$items=db()->query('SELECT i.*,c.nombre categoria FROM imagenes i LEFT JOIN categorias c ON c.id=i.categoria_id ORDER BY i.created_at DESC')->fetchAll();require dirname(__DIR__).'/includes/admin_header.php';
?>
<div class="panel-heading"><div><h1>Imágenes</h1><p>Biblioteca de recursos visuales del sitio.</p></div></div><div class="grid-2"><form class="card" method="post" enctype="multipart/form-data"><?=csrf_field()?><input type="hidden" name="form_action" value="<?=$current?'update':'create'?>"><?php if($current):?><input type="hidden" name="token_id" value="<?=e(encode_id((int)$current['id']))?>"><?php endif;?><h2><?=$current?'Editar imagen':'Nueva imagen'?></h2><?php if($errors):?><div class="error-list"><ul><?php foreach($errors as$er):?><li><?=e($er)?></li><?php endforeach;?></ul></div><?php endif;?><div class="field"><label>Título</label><input name="titulo" value="<?=e($current['titulo']??'')?>" required></div><div class="field"><label>Texto alternativo</label><input name="texto_alt" value="<?=e($current['texto_alt']??'')?>" required></div><div class="field"><label>Sección</label><input name="seccion" value="<?=e($current['seccion']??'')?>"></div><div class="field"><label>Categoría</label><select name="categoria_id"><option value="">Sin categoría</option><?php foreach($categories as$c):?><option value="<?=(int)$c['id']?>" <?=($current['categoria_id']??null)==$c['id']?'selected':''?>><?=e($c['nombre'])?></option><?php endforeach;?></select></div><div class="field"><label>Archivo</label><input type="file" name="archivo" accept="image/jpeg,image/png,image/webp" <?=$current?'':'required'?>><?php if($current):?><img src="<?=url($current['ruta'])?>" alt="Actual" style="max-height:150px;margin-top:10px"><?php endif;?></div><label><input type="checkbox" name="activo" style="width:auto" <?=!$current||$current['activo']?'checked':''?>> Activa</label><div class="actions"><button class="btn">Guardar</button><?php if($current):?><a class="btn btn-light" href="<?=url('admin/imagenes.php')?>">Cancelar</a><?php endif;?></div></form><div class="table-card"><div class="table-responsive"><table><thead><tr><th>Vista</th><th>Información</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($items as$it):?><tr><td><img src="<?=url($it['ruta'])?>" alt="<?=e($it['texto_alt'])?>" style="width:90px;height:60px;object-fit:cover;border-radius:8px"></td><td><strong><?=e($it['titulo'])?></strong><br><small><?=e($it['seccion']??'Sin sección')?></small></td><td><?=$it['activo']?'Activa':'Inactiva'?></td><td class="table-actions"><a class="btn btn-small btn-light" href="<?=url('admin/imagenes.php?t='.encode_id((int)$it['id']))?>">Editar</a><form method="post"><?=csrf_field()?><input type="hidden" name="form_action" value="delete"><input type="hidden" name="token_id" value="<?=e(encode_id((int)$it['id']))?>"><button class="btn btn-small btn-danger" data-confirm="¿Eliminar esta imagen?">Eliminar</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div>
<?php require dirname(__DIR__).'/includes/admin_footer.php';?>
